import React, { useState, useRef } from 'react';
import '../combinedSlideshow.css';

const CombinedSlideshow = ({ midfiSlides, hifiSlides }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [sliderPosition, setSliderPosition] = useState(50);
  const [clicked, setClicked] = useState(null);
  const containerRef = useRef(null);

  const goToSlide = (index) => {
    setCurrentIndex(index);
    setSliderPosition(50);
    setTimeout(() => setClicked(null), 400);
  };

  const nextSlide = () => {
    setClicked('next');
    goToSlide((currentIndex + 1) % midfiSlides.length);
  };

  const prevSlide = () => {
    setClicked('prev');
    goToSlide((currentIndex - 1 + midfiSlides.length) % midfiSlides.length);
  };

  const handleMove = (e) => {
    const container = containerRef.current;
    if (!container) return;

    const rect = container.getBoundingClientRect();
    const x = Math.max(0, Math.min(e.clientX - rect.left, rect.width));
    const percent = Math.round((x / rect.width) * 100);
    setSliderPosition(percent);
  };

  return (
    <div className="combined-slideshow">
      

      {/* Comparison Images */}

      <div className="slideshow-wrapper">
        {/* Arrows */}
      <div className="arrow prev" onClick={prevSlide}>
        ❮
        {clicked === 'prev' && <span className="pulse" />}
      </div>
      <div className="arrow next" onClick={nextSlide}>
        ❯
        {clicked === 'next' && <span className="pulse" />}
      </div>
      <div
        className="comparison-container"
        ref={containerRef}
        onMouseMove={handleMove}
        onTouchMove={(e) => handleMove(e.touches[0])}
      >
        <div className="before">
          <img
            src={midfiSlides[currentIndex].image}
            alt={`Mid-fi: ${midfiSlides[currentIndex].caption}`}
          />
        </div>

        <div className="label">Mid-fi</div>
        <div className="label hifi">Hi-fi</div>

        <div className="after" style={{ width: `${sliderPosition}%` }}>
          <img
            src={hifiSlides[currentIndex].image}
            alt={`Hi-fi: ${hifiSlides[currentIndex].caption}`}
          />
        </div>

        <div className="slider-handle" style={{ left: `${sliderPosition}%` }}>
          <div className="slider-arrow">↔</div>
        </div>
      </div>
      </div>

     

      <div className="slide-caption">{midfiSlides[currentIndex].caption}</div>

      <div className="slideshow-controls">
        <div className="slide-indicators">
          {midfiSlides.map((_, index) => (
            <span
              key={index}
              className={`indicator ${index === currentIndex ? 'active' : ''}`}
              onClick={() => goToSlide(index)}
            />
          ))}
        </div>
      </div>
    </div>
  );
};

export default CombinedSlideshow;