import React, { useState } from 'react';
import '../slideshow.css';

const Slideshow = ({ slides }) => {
  const [slideIndex, setSlideIndex] = useState(0);
  const [direction, setDirection] = useState('');
  const [clicked, setClicked] = useState(null); // 'prev' or 'next'

  const plusSlides = (n, type) => {
    setDirection(n > 0 ? 'right' : 'left');
    setClicked(type); // trigger pulse
    showSlides(slideIndex + n);

    // reset pulse after animation
    setTimeout(() => setClicked(null), 400);
  };

  const showSlides = (n) => {
    let newIndex = n;
    if (n >= slides.length) newIndex = 0;
    else if (n < 0) newIndex = slides.length - 1;
    setSlideIndex(newIndex);
  };

  return (
    <div className='slideshow-wrapper'>
      
        <div className="slideshow-wrapper">
            <div className="slideshow-container">
            {slides.map((slide, index) => (
                <div
                key={index}
                className={`mySlides ${index === slideIndex ? `active ${direction}` : ''}`}
                >
                <img src={slide.image} style={{ width: '100%' }} alt={`Slide ${index + 1}`} />
                {/* <div className="text">{slide.caption}</div> */}
                </div>
            ))}
            
            </div>
            <a className="prev cta-shadows" onClick={() => plusSlides(-1, 'prev')}>
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                    <path d="M15 18L9 12L15 6" stroke="black" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                </svg>
                {clicked === 'prev' && <span className="pulse" />}
            </a>
            <a className="next cta-shadows" onClick={() => plusSlides(1, 'next')}>
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                    <path d="M9 6L15 12L9 18" stroke="black" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                </svg>
                {clicked === 'next' && <span className="pulse" />}
            </a>
            
        </div>

        <div className="slide-caption">
          {slides[slideIndex].caption}
        </div>

    </div>

  );
};

export default Slideshow;