import { useState } from 'react';

const PRESET_BUBBLES = [
  { id: 0, left: '10%', size: 60, height: 640, duration: 9 },
  { id: 1, left: '25%', size: 54, height: 330, duration: 5 },
  { id: 2, left: '40%', size: 40, height: 410, duration: 6.5 },
  { id: 3, left: '55%', size: 48, height: 290, duration: 4 },
  { id: 4, left: '70%', size: 60, height: 450, duration: 6.5 },
  { id: 5, left: '85%', size: 80, height: 720, duration: 8.2 },
];

function createParticles() {
  return Array.from({ length: 12 }).map(() => ({
    angle: Math.random() * Math.PI * 2,
    distance: Math.random() * 80 + 30, // 30 to 110px
    size: Math.random() * 4 + 3,       // 3 to 7px
    speed: Math.random() * 0.3 + 0.4,  // 0.4s to 0.7s
  }));
}

export default function Bubble() {
  const [bubbles, setBubbles] = useState(
    PRESET_BUBBLES.map((b) => ({ ...b, burst: false, key: Date.now() + '-' + b.id }))
  );

  const handleBurst = (id, e) => {
    const rect = e?.target?.getBoundingClientRect();
    const bottom = rect ? window.innerHeight - rect.top : PRESET_BUBBLES[id].height;

    setBubbles((prev) =>
      prev.map((b) =>
        b.id === id
          ? {
              ...b,
              burst: true,
              burstBottom: bottom,
              particles: createParticles(),
            }
          : b
      )
    );

    setTimeout(() => {
      setBubbles((prev) =>
        prev.map((b) =>
          b.id === id
            ? {
                ...PRESET_BUBBLES[id],
                burst: false,
                key: Date.now() + '-' + id,
              }
            : b
        )
      );
    }, 800);
  };

  return (
    <>
      {bubbles.map((bubble) =>
        !bubble.burst ? (
          <div
            key={bubble.key}
            className="bubble"
            style={{
              left: bubble.left,
              width: `${bubble.size}px`,
              height: `${bubble.size}px`,
              animationDuration: `${bubble.duration}s`,
              '--float-height': `${bubble.height}px`,
            }}
            onAnimationEnd={(e) => handleBurst(bubble.id, e)}
            onMouseEnter={(e) => handleBurst(bubble.id, e)}
          />
        ) : (
          <div
            key={bubble.key}
            className="burst-container"
            style={{
              left: bubble.left,
              bottom: `${bubble.burstBottom || bubble.height}px`,
            }}
          >
            {bubble.particles.map((p, i) => {
              const x = Math.cos(p.angle).toFixed(2);
              const y = Math.sin(p.angle).toFixed(2);
              return (
                <span
                  key={i}
                  className="particle"
                  style={{
                    '--x': x,
                    '--y': y,
                    '--distance': `${p.distance}px`,
                    '--size': `${p.size}px`,
                    animationDuration: `${p.speed}s`,
                  }}
                />
              );
            })}
          </div>
        )
      )}
    </>
  );
}