import React, {useState} from 'react';
import '../shimmer.css';

const ShimmerBlock = ({ logoBefore, logoAfter, logoText = '', dotColor = '#000', socialLink }) => {
  const cols = 64;
  const rows = 20;
  const totalDots = cols * rows;
  const [isHovered, setIsHovered] = useState(false);


  return (
    <div className="shimmer-wrapper">

      <a className="shimmer-grid"
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      href = {socialLink}
      target="_blank"
      rel="noreferrer"
      >
        <div className="dots-mask">
          {Array.from({ length: totalDots }).map((_, index) => (
            <div
              key={index}
              className="dot"
              style={{
                backgroundColor: dotColor,
                animationDelay: `${Math.random() * 2}s`,
                animationDuration: `${2 + Math.random() * 3}s`,
              }}
            ></div>
          ))}
        </div>

        <div className="logo-container">
          <div className="logo-wrapper">
            <div className="logo-before">{logoBefore}</div>
            <div className="logo-after">{logoAfter}</div>
          </div>
          <span className="logo-text" 
            
            style={{ color: isHovered ? dotColor : '#000', transition: "color 0.5s ease" }}
          >{logoText}</span>
        </div>
      </a>
    </div>
  );
};

export default ShimmerBlock;