import React, { useEffect, useRef } from 'react';
import { CDN } from '../config';

function GoToTop() {
  const goToTopRef = useRef(null);

  useEffect(() => {
    const goToTopButton = goToTopRef.current;

    if (!goToTopButton) return;

    const handleScroll = () => {
      goToTopButton.classList.toggle("goappear", window.scrollY > 600);
    };

    const handleClick = () => {
      window.scrollTo({
        top: 0,
        behavior: "smooth"
      });
    };

    // Add event listeners
    window.addEventListener("scroll", handleScroll);
    goToTopButton.addEventListener("click", handleClick);

    // Cleanup function
    return () => {
      window.removeEventListener("scroll", handleScroll);
      goToTopButton.removeEventListener("click", handleClick);
    };
  }, []); // Empty dependency array means this runs once on mount

  return (
    <div 
      ref={goToTopRef} 
      id="goToTop" 
      className="cta-shadows go-to-top"
    >
      {/* <img src={`${CDN}/icons/Up_arrow.svg`} alt="Go to top" /> */}
        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M12 6V18M12 6L7 11M12 6L17 11" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
        </svg>
    </div>
  );
}

export default GoToTop;