import React, { useRef, useEffect } from 'react';
import { gsap } from 'gsap';
import SplitType from 'split-type';

const AnimatedHeader = ({ children }) => {
  const headerRef = useRef();

  useEffect(() => {
    const headerElement = headerRef.current;
    if (!headerElement) return;

    // Split by words first, then characters - preserves spaces
    const split = new SplitType(headerElement, { 
      types: 'words,chars',
      wordClass: 'animated-word',
      charClass: 'animated-char'
    });

    // Filter out space characters
    const animatableChars = [...split.chars].filter(
      char => char.innerHTML !== ' ' && char.textContent.trim() !== ''
    );

    // Set initial styles only for animatable characters
    gsap.set(animatableChars, {
      display: 'inline-block',
      fontVariationSettings: "'wght' 600",
      transformOrigin: 'center bottom'
    });

    const handleMouseMove = (e) => {
      const rect = headerElement.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      animatableChars.forEach((char) => {
        const charRect = char.getBoundingClientRect();
        const charCenter = charRect.left + charRect.width/2 - rect.left;
        const distance = Math.abs(mouseX - charCenter);
        const influence = Math.max(0, 1 - distance / (charRect.width * 1.5));
        
        gsap.to(char, {
            fontVariationSettings: `'wght' ${600 + 300 * influence}`,
            scale: 1 + 0.2 * influence,
            duration: 0.2,
            // color: `rgba(51, 84, 255, ${influence})`
            color: influence > 0 ? 'rgba(51, 84, 255, ${influence})' : '#000'
        });
      });
    };

    const resetAll = () => {
      gsap.to(animatableChars, {
        fontVariationSettings: "'wght' 600",
        scale: 1,
        duration: 0.4,
        ease: "elastic.out(1, 0.3)"
      });
    };

    headerElement.addEventListener('mousemove', handleMouseMove);
    headerElement.addEventListener('mouseleave', resetAll);
    
    return () => {
      split.revert();
      headerElement.removeEventListener('mousemove', handleMouseMove);
      headerElement.removeEventListener('mouseleave', resetAll);
      gsap.killTweensOf(animatableChars);
    };
  }, []);

  return (
    <h1 
      ref={headerRef}
      className='movable-header'
      style={{
        fontFamily: "'Lexend Variable', sans-serif",
        position: 'relative',
        whiteSpace: 'normal' // Crucial for space preservation
      }}
    >
      {children}
    </h1>
  );
};

export default AnimatedHeader;